    size_t length = 0;

    const char *jpeg_version = "JPEG-6b";
    const char *description = "Joint Photographic Experts Group JFIF format";

    /* JPEG format identifiers */
    const char *const formats[] = { "JPE", "JPEG", "JPG", "JPS", "PJPEG", NULL };

    for (size_t i = 0; formats[i] != NULL; i++)
    {
        magick_info = SetMagickInfo(formats[i]);
        if (magick_info == (MagickInfo *) NULL)
            continue;

        magick_info->decoder = ReadJPEGImage;
        magick_info->encoder = WriteJPEGImage;
        magick_info->thread_support = MagickFalse;

        /* Determine thread support based on JPEG library version */
#if defined(JPEG_LIB_VERSION) && (JPEG_LIB_VERSION >= 62)
        magick_info->thread_support = MagickTrue;
#endif

        magick_info->description = (char *) description;
        magick_info->version = (char *) jpeg_version;
        magick_info->mime_type = "image/jpeg";

        if (RegisterMagickInfo(magick_info) != MagickFalse)
            length++;
