size_t RegisterJPEGImage(void) {
  const char *version = "JPEG";
  const char *description = "Joint Photographic Experts Group JFIF format";
  size_t count = 0;

  count += SetMagickInfo("JPE", version, description);
  count += SetMagickInfo("JPEG", version, description);
  count += SetMagickInfo("JPG", version, description);
  count += SetMagickInfo("JPS", version, description);
  count += SetMagickInfo("PJPEG", version, description);

  // Determine thread support based on JPEG library version
  int thread_support = (JPEG_LIB_VERSION >= 70);
  for (size_t i = 0; i < count; ++i) {
    MagickInfo *entry = GetMagickInfo("JPEG", NULL);
    if (entry != NULL) {
      entry->decoder = ReadJPEGImage;
      entry->encoder = WriteJPEGImage;
      entry->thread_support = thread_support;
      entry->mime_type = "image/jpeg";
    }
  }

  return count;
}
